insert into public.trechos (fonte_id,ente,caminhos,referencia,resumo) select id,'BR',array['normas'::extensions.ltree],null,'Hierarquia: a regra geral é o MCASP atualizado e a STN federal sempre deve ser respeitada. Quando o estado tem regulamento próprio (ex.: Espírito Santo, Tabela TCE-ES), ele prevalece naquele estado.' from public.fontes where titulo like 'Diretrizes do sistema%';
insert into public.trechos (fonte_id,ente,caminhos,referencia,resumo) select id,'BR',array['despesa.consumo.criterios'::extensions.ltree,'despesa.permanente'::extensions.ltree],'art. 15, § 2º','Para efeito de classificação da despesa, considera-se material permanente o de duração superior a dois anos.' from public.fontes where titulo like 'Lei nº 4.320%';
insert into public.trechos (fonte_id,ente,caminhos,referencia,resumo) select id,'BR',array['despesa.consumo.criterios'::extensions.ltree],'art. 3º','Material é de consumo se atender a pelo menos um critério: durabilidade (perde condições de uso em até dois anos), fragilidade (quebradiço ou deformável, irrecuperável), perecibilidade (sujeito a deterioração), incorporabilidade (incorporado a outro bem sem poder ser retirado sem prejuízo) ou transformabilidade (adquirido para transformação). Se não atender a nenhum, é permanente.' from public.fontes where titulo like 'Portaria STN nº 448%';
insert into public.trechos (fonte_id,ente,caminhos,referencia,resumo) select id,'BR',array['normas'::extensions.ltree,'despesa'::extensions.ltree],null,'A natureza da despesa é formada por categoria econômica, grupo de natureza, modalidade de aplicação e elemento de despesa; o desdobramento em subelementos é facultativo e definido por cada ente.' from public.fontes where titulo like 'Portaria Interministerial STN/SOF nº 163%';
insert into public.trechos (fonte_id,ente,caminhos,referencia,resumo) select id,'BR',array['contabil.imobilizado.terreno'::extensions.ltree,'contabil.imobilizado.depreciacao'::extensions.ltree],'Depreciação','Terrenos têm vida útil ilimitada e não são depreciados. Terreno e edificação são ativos separados, mesmo adquiridos juntos: o valor do terreno é registrado à parte e só a edificação deprecia.' from public.fontes where titulo like 'NBC TSP 07%';
insert into public.trechos (fonte_id,ente,caminhos,referencia,resumo) select id,'AC',array['contabil.imobilizado.tombamento'::extensions.ltree],'art. 30','Na aquisição de bem móvel, o fiscal do contrato atesta a nota fiscal, o bem é incorporado ao sistema de gestão patrimonial e, após o tombamento, o responsável pelo patrimônio também atesta o documento fiscal.' from public.fontes where titulo like 'IN CGE-AC nº 3/2026%';
insert into public.trechos (fonte_id,ente,caminhos,referencia,resumo) select id,'ES',array['normas'::extensions.ltree,'despesa'::extensions.ltree],null,'No Espírito Santo, a classificação vai até o subelemento e usa exclusivamente os códigos da Tabela de Natureza da Despesa do TCE-ES, que prevalece sobre a base federal no estado.' from public.fontes where titulo like 'Tabela de Natureza da Despesa TCE-ES%';
insert into public.trechos (fonte_id,ente,caminhos,referencia,resumo) select id,'ES',array['unidade_medida'::extensions.ltree],'Anexo VI','No Espírito Santo, a unidade de medida deve ser uma das unidades da Tabela Auxiliar 22 (IN TCE-ES nº 68/2020, Anexo VI).' from public.fontes where titulo like 'IN TCE-ES nº 68/2020%';
